using UnityEngine;
using FPS.Animation;

namespace FPS
{
    /// <summary>
    /// Animation data of the soldier characters (Military pack): the locomotion controller, avatar masks, weapon hold
    /// poses and one-shot clips. Generated by Tools > FPS > Build Military Animations into Resources/CharacterAnimSet.
    /// Controller parameters: VelX / VelZ / Speed (m/s, character space), Crouch, Prone (0..1), Grounded, VertSpeed,
    /// Slide, Vault, Mantle, VaultT (0..1), Dead, DeadForward, AnimSpeed.
    /// </summary>
    public class CharacterAnimSet : ScriptableObject
    {
        public RuntimeAnimatorController controller;

        [Header("Masks")]
        [Tooltip("Arms + fingers: weapon hold poses")] public AvatarMask armsMask;
        [Tooltip("Head + arms + fingers (no spine / hips): one-shots over the locomotion")] public AvatarMask upperBodyMask;
        public AvatarMask fingersMask;

        [Header("Weapon hold (overlay poses)")]
        public AnimSequence rifleHold;
        public AnimSequence pistolHold;
        public AnimSequence unarmedHold;

        [Header("One-shots (upper body)")]
        public AnimationClip reloadRifle;
        public AnimationClip throwGrenade;
        public AnimationClip punch;
        public AnimationClip knifeSlash;

        [Header("Measured")]
        [Tooltip("Eye height of the model standing in the idle pose at scale 1 (m)")] public float restEyeHeight = 1.75f;
        [Tooltip("Eye point relative to the head bone in the character's upright frame")] public Vector3 eyeOffset = new Vector3(0f, 0.085f, 0.105f);
        [Tooltip("Ground speeds the locomotion rings were built for (walk, jog, sprint, crouch, prone)")] public Vector4 speeds = new Vector4(1.45f, 4.6f, 7.4f, 2.5f);
        public float proneSpeed = 1.15f;

        static CharacterAnimSet instance;
        static bool loaded;

        public static CharacterAnimSet Instance
        {
            get
            {
                if (!loaded) { instance = Resources.Load<CharacterAnimSet>("CharacterAnimSet"); loaded = true; }
                return instance;
            }
        }
    }
}
